import numpy as np
from collections import deque

demo_input = [[int(x) for x in line.split()] for line in demo_input_lines]
demo_output = [[int(x) for x in line.split()] for line in demo_output_lines]
input_arr = np.array(demo_input)
output_arr = np.array(demo_output)
changed_to_4 = input_arr != output_arr

rows = len(demo_input)
cols = len(demo_input[0])

visited = [[False] * cols for _ in range(rows)]
components = []

def bfs(start_r, start_c, vis):
    component = []
    queue = deque([(start_r, start_c)])
    vis[start_r][start_c] = True
    while queue:
        cr, cc = queue.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = cr + dr, cc + dc
            if 0 <= nr < rows and 0 <= nc < cols and not vis[nr][nc]:
                if demo_input[nr][nc] == 3:
                    vis[nr][nc] = True
                    queue.append((nr, nc))
                    component.append((nr, nc))
    return component

for r in range(rows):
    for c in range(cols):
        if demo_input[r][c] == 3 and not visited[r][c]:
            comp = bfs(r, c, vis)
            if comp:
                components.append(comp)

# Track which components changed
comp_changed = set(comp_changed = set()]
for r in range(rows):
    for c in range(cols):
        if changed_to_4[r, c]:
            comp_changed.add((r, c))

# Check if component forms a solid rectangle
def is_rectangle(comp):
    if not comp:
        return False
    rows_st, rows_ed = min(r for r,c in comp), max(r for r,c in comp)
    cols_st, cols_ed = min(c for r,c in comp), max(c for r,c in comp)
    expected_count = (rows_ed - rows_st + 1) * (cols_ed - cols_st + 1)
    return len(comp) == expected_count

changed_rects = 0
both_rects = 0
unchanged_non_rects = 0
unchanged_rects = 0

for comp in components:
    comp_set = set(comp)
    is_rect = is_rectangle(comp)
    is_changed = len(comp_set & comp_changed) > 0

    if is_rect and is_changed:
        changed_rects += 1
    elif is_rect and not is_changed:
        unchanged_rects += 1
    elif not is_rect and is_changed:
        both_rects += 1
    elif not is_rect and not is_changed:
        unchanged_non_rects += 1

print(f"Changed rectangles: {changed_rects}")
print(f"Changed non-rectangles: {both_rects}")
print(f"Unchanged rectangles: {unchanged_rects}")
print(f"Unchanged non-rectangles: {unchanged_non_rects}")

# Check what makes changed components different
print("\n\nChanged rectangle details:")
for comp in components:
    comp_set = set(comp)
    if len(comp_set & comp_changed) > 0:
        print(f"  {comp}")

print("\n\nUnchanged rectangle details:")
for comp in components:
    comp_set = set(comp)
    if is_rectangle(comp) and len(comp_set & comp_changed) == 0:
        print(f"  {comp}")

